# ---------------------------------------------------------------------------
# Builds a clean handover zip of MedConsult.
#
# Run from the project root:
#   powershell -ExecutionPolicy Bypass -File package-for-client.ps1
#
# Deliberately EXCLUDED from the zip:
#   .env            real credentials: mail password, API keys, JWT secret
#   node_modules    hundreds of MB, regenerated by `npm install`
#   dist            build output, regenerated by `npm run build`
#   uploads         medical files uploaded during testing
#   *.log           local noise
#
# The .env.example templates ARE included. They carry no secrets and are what
# the client copies to create their own .env.
# ---------------------------------------------------------------------------

$ErrorActionPreference = 'Stop'

$root    = $PSScriptRoot
$stamp   = Get-Date -Format 'yyyy-MM-dd'
$staging = Join-Path $env:TEMP "medconsult-package-$stamp"
$zipPath = Join-Path (Split-Path $root -Parent) "medconsult-$stamp.zip"

Write-Host ''
Write-Host 'Packaging MedConsult for handover' -ForegroundColor Cyan
Write-Host '---------------------------------'

if (Test-Path $staging) { Remove-Item $staging -Recurse -Force }
if (Test-Path $zipPath) { Remove-Item $zipPath -Force }

# Copy the tree, then prune. Simpler to reason about than an include-list, and
# a newly added source folder can never be silently left out of the handover.
Write-Host 'Copying project files...'
New-Item -ItemType Directory -Path $staging -Force | Out-Null
Copy-Item -Path (Join-Path $root '*') -Destination $staging -Recurse -Force

$prune = @(
    'node_modules',
    'dist',
    'uploads',
    '.git',
    '.vscode',
    '.idea',
    'coverage'
)

Write-Host 'Removing build output and dependencies...'
foreach ($name in $prune) {
    Get-ChildItem -Path $staging -Filter $name -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { $_.PSIsContainer } |
        ForEach-Object { Remove-Item $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
}

# The important one. A leaked .env hands over a live mail password and every
# API key, so this runs as its own step and reports exactly what it removed
# rather than doing it silently.
Write-Host 'Removing credential files...' -ForegroundColor Yellow
$removedSecrets = @()
Get-ChildItem -Path $staging -Force -Recurse -ErrorAction SilentlyContinue |
    Where-Object { -not $_.PSIsContainer -and $_.Name -like '.env*' -and $_.Name -ne '.env.example' } |
    ForEach-Object {
        $removedSecrets += $_.FullName.Substring($staging.Length + 1)
        Remove-Item $_.FullName -Force
    }
foreach ($f in $removedSecrets) { Write-Host "    excluded  $f" -ForegroundColor DarkYellow }

Get-ChildItem -Path $staging -Filter '*.log' -Recurse -Force -ErrorAction SilentlyContinue |
    Remove-Item -Force -ErrorAction SilentlyContinue

# Refuse to ship rather than ship a leak.
$leaks = Get-ChildItem -Path $staging -Force -Recurse -ErrorAction SilentlyContinue |
    Where-Object { -not $_.PSIsContainer -and $_.Name -like '.env*' -and $_.Name -ne '.env.example' }
if ($leaks) {
    Write-Host ''
    Write-Host 'ABORTED: credential files survived the cleanup:' -ForegroundColor Red
    $leaks | ForEach-Object { Write-Host "    $($_.FullName)" -ForegroundColor Red }
    exit 1
}

# Both templates must survive, or the client has nothing to copy from.
foreach ($t in @('server\.env.example', 'client\.env.example')) {
    if (-not (Test-Path (Join-Path $staging $t))) {
        Write-Host "ABORTED: $t is missing. The client would have no template." -ForegroundColor Red
        exit 1
    }
}

# Compress-Archive on PowerShell 5.1 writes BACKSLASH path separators, which
# the ZIP spec forbids. Windows tolerates it, macOS and Linux do not: the
# client would extract a flat pile of files with literal backslashes in their
# names instead of a folder tree. Building the archive entry by entry lets us
# write spec-correct forward slashes.
Write-Host 'Creating zip...'
Add-Type -AssemblyName System.IO.Compression | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem | Out-Null

$archive = [System.IO.Compression.ZipFile]::Open($zipPath, 'Create')
try {
    Get-ChildItem -Path $staging -Recurse -File -Force | ForEach-Object {
        $rel = $_.FullName.Substring($staging.Length + 1).Replace('\', '/')
        [System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile(
            $archive,
            $_.FullName,
            $rel,
            [System.IO.Compression.CompressionLevel]::Optimal) | Out-Null
    }
}
finally {
    $archive.Dispose()
}

$sizeMb  = [math]::Round((Get-Item $zipPath).Length / 1MB, 1)
$fileNum = (Get-ChildItem -Path $staging -Recurse -File -Force).Count

Remove-Item $staging -Recurse -Force

Write-Host ''
Write-Host 'Done.' -ForegroundColor Green
Write-Host "  $zipPath"
Write-Host "  $fileNum files, $sizeMb MB"
Write-Host ''
Write-Host 'The client should read README.md first. Setup is the opening section.'
Write-Host ''
